function Invoice({ bill, store, close, edit }: { bill: Bill; store: FleetStore; close: () => void; edit: () => void }) {
  const balance = billBalance(bill);
  return <div className="invoice-backdrop"><div className="invoice-dialog">
    <div className="invoice-toolbar"><Button secondary onClick={close}><X size={17}/>Close</Button><Button secondary onClick={edit}><FileText size={17}/>Edit bill</Button><Button onClick={() => window.print()}><Printer size={17}/>Print / PDF</Button></div>
    <article className="invoice-sheet op-invoice">
      <header className="invoice-brand"><Gauge size={30}/><h2>{store.company.name}</h2></header><h1>TAX INVOICE</h1>
      <section className="invoice-company"><p>{store.company.address}</p><p>Mobile: {store.company.mobile} | Email: {store.company.email}</p></section>
      <section className="invoice-meta"><p><b>Bill No:</b> INV-{String(bill.number).padStart(4, "0")}</p><p><b>Bill Date:</b> {fmt(bill.billDate)}</p><p className="invoice-bill-to"><b>Bill To:</b> {bill.client.firmName}<br/><span>{bill.client.ownerName}<br/>{bill.client.address}<br/>{bill.client.mobile} · {bill.client.email}</span></p></section>
      <table className="invoice-table"><thead><tr><th>Vehicle / period</th><th>Booked</th><th>Present</th><th>Absent</th><th>Rate / day</th><th>Amount</th></tr></thead><tbody>{bill.vehicleLines.map((line) => { const vehicle = store.vehicles.find((item) => item.id === line.vehicleId); return <tr key={line.id}><td><b>{line.label ?? `${vehicle?.number ?? "Vehicle"} · ${vehicle?.type ?? ""}`}{line.quantity && line.quantity > 1 ? ` × ${line.quantity}` : ""}</b><br/>{fmt(line.startDate)} to {fmt(line.endDate)}<br/>Campaign vehicle attendance</td><td>{line.bookedDays}</td><td>{line.advertisementDays}</td><td>{line.offDays}</td><td>{money(line.dailyRate)}</td><td>{money(line.advertisementDays * line.dailyRate * (line.quantity ?? 1))}</td></tr>; })}</tbody></table>
      {bill.charges.length > 0 && <table className="invoice-expenses"><thead><tr><th>Other charges / discount</th><th>Details</th><th>Amount</th></tr></thead><tbody>{bill.charges.map((charge) => <tr key={charge.id}><td>{charge.category}</td><td>{charge.description}</td><td>{charge.category === "Discount" ? "−" : ""}{money(charge.amount)}</td></tr>)}</tbody></table>}
      {(bill.advanceReceived > 0 || bill.payments.length > 0) && <table className="invoice-expenses op-payment-history"><thead><tr><th>Payment date</th><th>Receipt / reference</th><th>Amount received</th></tr></thead><tbody>{bill.advanceReceived > 0 && <tr><td>{fmt(bill.billDate)}</td><td>Advance received</td><td>{money(bill.advanceReceived)}</td></tr>}{bill.payments.map((payment) => <tr key={payment.id}><td>{fmt(payment.date)}</td><td>{payment.reference || payment.note || "Installment"}</td><td>{money(payment.amount)}</td></tr>)}</tbody></table>}
      <section className="op-invoice-total"><p><span>Total</span><b>{money(bill.total)}</b></p><p><span>Total received</span><b>−{money(billPaid(bill))}</b></p><p><span>Outstanding</span><strong>{money(balance)}</strong></p></section>
      <footer className="invoice-footer"><div><h3>Bank details for RTGS / NEFT</h3><p><b>Account:</b> {store.company.accountName}</p><p><b>Bank:</b> {store.company.bankName} · {store.company.branch}</p><p><b>A/C No:</b> {store.company.accountNumber || "Update in company settings"}</p><p><b>IFSC:</b> {store.company.ifsc || "Update in company settings"}</p></div><div><p>For {store.company.name}</p><b>Authorized Signatory</b></div></footer>
    </article>
  </div></div>;
}

